enum ipsec_rcv_value ipsec_rcv_esp_checks ( struct ipsec_rcv_state * irs , struct sk_buff * skb ) { if ( ( irs -> proto == IPPROTO_ESP ) && ( ( skb -> len - irs -> iphlen ) % 4 ) ) { printk ( "klips_error:ipsec_rcv: " "got packet with content length %d - %d = %d from %s -- should be on 4 octet boundary, packet dropped\n" , skb -> len , irs -> iphlen , skb -> len - irs -> iphlen , irs -> ipsaddr_txt ) ; if ( irs -> stats ) { irs -> stats -> rx_errors ++ ; } return IPSEC_RCV_BADLEN ; } if ( skb -> len < ( irs -> hard_header_len + sizeof ( iphdr ) + sizeof ( esphdr ) ) ) { KLIPS_PRINT ( debug_rcv & DB_RX_INAU , "klips_debug:ipsec_rcv: " "runt esp packet of skb->len=%d received from %s, dropped.\n" , skb -> len , irs -> ipsaddr_txt ) ; return IPSEC_RCV_BADLEN ; } irs -> protostuff . espstuff . espp = ( esphdr * ) skb_transport_header ( skb ) ; irs -> said . spi = irs -> protostuff . espstuff . espp -> esp_spi ; return IPSEC_RCV_OK ; } 